messages.content:
Tool response:
Tool: update_shipping_address
Description: Update Shipping Address
Parameters:
    {
      "type": "object",
      "properties": {
        "user_id": {
          "type": "integer",
          "description": "The ID of the user whose shipping address is being updated",
          "title": "User Id"
        },
        "street": {
          "type": "string",
          "title": "Street",
          "description": "The street address"
        },
        "apartment": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Apartment",
          "description": "The apartment or unit number (optional)"
        },
        "city": {
          "type": "string",
          "title": "City",
          "description": "The city"
        },
        "state": {
          "type": "string",
          "title": "State",
          "description": "The state"
        },
        "postal_code": {
          "type": "string",
          "title": "Postal Code",
          "description": "The postal code"
        },
        "country": {
          "type": "string",
          "title": "Country",
          "description": "The country (defaults to 'US')",
          "default": "US"
        }
      },
      "required": [
        "user_id",
        "street",
        "city",
        "state",
        "postal_code"
      ]
    }
